ENDPOINT = "http://127.0.0.1:11434/api/chat"

DEFAULT_MODEL = "llama2-uncensored"
class KokoroVoice:
    """Local neural speech; lazy loading keeps the UI responsive at startup."""
    def __init__(self):
        self.lock = threading.RLock()
        self.work_lock = threading.Lock()
        self.generation = 0
        self.engine = None
        self.audio = None

    @staticmethod
    def model_directory():
        base = Path(sys.executable).parent if getattr(sys, 'frozen', False) else Path(__file__).resolve().parent
        candidates = [base / 'voices']
        if hasattr(sys, '_MEIPASS'):
            candidates.append(Path(sys._MEIPASS) / 'voices')
        candidates.append(Path(os.environ.get('LOCALAPPDATA', str(Path.home() / '.local/share'))) / 'TechAidIO' / 'voices')
        for folder in candidates:
            if all((folder / name).is_file() for name in ('kokoro-v1.0.onnx', 'voices-v1.0.bin')):
                return folder
        raise RuntimeError('Kokoro voice files are missing. Run Setup_Mood.bat from the downloaded Mood folder, then restart Mood. Keep the voices folder with the Python file.')

    def stop(self):
        with self.lock:
            self.generation += 1
            if self.audio is not None:
                self.audio.stop()
            return self.generation

    @staticmethod
    def speech_chunks(text):
        # Code remains visible and copyable in chat, but is not read aloud.
        text = re.sub(r'```[\s\S]*?(?:```|$)', ' Code is shown in the chat. ', text)
        text = re.sub(r'\[([^]]+)\]\([^)]+\)', r'\1', text)
        text = re.sub(r'(?m)^\s*#{1,6}\s+', '', text)
        text = text.replace('**', '').replace('`', '')
        words = text.split()
        chunk = ''
        for word in words:
            # Bound unusual long tokens as well as ordinary sentences.
            for offset in range(0, len(word), 200):
                piece = word[offset:offset + 200]
                if chunk and len(chunk) + len(piece) + 1 > 220:
                    yield chunk
                    chunk = ''
                chunk += (' ' if chunk else '') + piece
        if chunk:
            yield chunk

    def run(self, text, token):
        with self.work_lock:
            with self.lock:
                if token != self.generation:
                    return
            if self.engine is None:
                folder = self.model_directory()
                try:
                    from kokoro_onnx import Kokoro
                    import sounddevice as sd
                except ImportError as exc:
                    raise RuntimeError('Kokoro speech dependencies are missing. Run Setup_Mood.bat and launch with Run_Mood.bat, using Python 3.12.') from exc
                self.engine = Kokoro(str(folder / 'kokoro-v1.0.onnx'), str(folder / 'voices-v1.0.bin'))
                self.audio = sd
            for chunk in self.speech_chunks(text):
                with self.lock:
                    if token != self.generation:
                        return
                samples, sample_rate = self.engine.create(chunk, voice='af_heart', speed=1.0, lang='en-us')
                with self.lock:
                    if token != self.generation:
                        return
                    self.audio.play(samples, sample_rate, blocking=False)
                self.audio.wait()

DEFAULT_PROMPT = (
    "Your name is Mood, the AI assistant in TechAid IO. "
    "Be helpful, clear, and accurate. Explain things simply. "
    "Do not claim you performed actions that you have not performed."
)

