# -------------------- MANAGED LOCAL RUNTIME --------------------

class LocalRuntime:
    """Reuse an existing server or start the shipped standalone runtime."""

    def __init__(self):
        self.base = "http://127.0.0.1:11434"
        self.process = None
        self.stopped = threading.Event()
        self.lock = threading.Lock()
        self.opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))

    def request(self, path, payload=None, timeout=3):
        data = None if payload is None else json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(self.base + path, data=data,
                                     headers={"Content-Type": "application/json"})
        return self.opener.open(req, timeout=timeout)

    def available(self):
        try:
            with self.request("/api/version") as response:
                return bool(json.load(response).get("version"))
        except (OSError, ValueError):
            return False

    def start(self, report):
        global ENDPOINT
        if self.stopped.is_set():
            raise RuntimeError("App closed.")
        if self.available():
            ENDPOINT = self.base + "/api/chat"
            return
        if self.process and self.process.poll() is None:
            raise RuntimeError("The bundled AI engine is not responding. Restart TechAid IO.")
        report("Starting Mood's local AI engine…")
        root = Path(sys.executable).parent if getattr(sys, "frozen", False) else Path(__file__).resolve().parent
        candidates = [root / "runtime" / "ollama.exe",
                      Path(os.environ.get("LOCALAPPDATA", "")) / "Programs" / "Ollama" / "ollama.exe"]
        binary = next((str(path) for path in candidates if path.is_file()), None)
        binary = binary or shutil.which("ollama")
        if not binary:
            raise RuntimeError("Mood's AI engine is missing. Extract the complete shared Mood folder "
                               "and keep its runtime folder next to Mood.exe. Then press Retry setup.")
        # Keep our own server separate from a user's existing Ollama installation.
        self.base = "http://127.0.0.1:11435"
        if self.available():
            ENDPOINT = self.base + "/api/chat"
            return
        env = os.environ.copy()
        env["OLLAMA_HOST"] = "127.0.0.1:11435"
        env["OLLAMA_NO_CLOUD"] = "1"
        # Default model directory is shared with standard Ollama to avoid duplicate downloads.
        env.pop("OLLAMA_MODELS", None)
        logs = Path(os.environ.get("LOCALAPPDATA", str(Path.home()))) / "TechAidIO"
        logs.mkdir(parents=True, exist_ok=True)
        with (logs / "engine.log").open("ab") as log:
            self.process = subprocess.Popen(
                [binary, "serve"], env=env, stdin=subprocess.DEVNULL,
                stdout=log, stderr=log,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        if self.stopped.is_set():
            self.close()
            raise RuntimeError("App closed.")
        deadline = time.monotonic() + 90
        while time.monotonic() < deadline:
            if self.stopped.is_set():
                raise RuntimeError("App closed.")
            if self.available():
                ENDPOINT = self.base + "/api/chat"
                return
            if self.process.poll() is not None:
                raise RuntimeError("AI engine could not start. See %LOCALAPPDATA%/TechAidIO/engine.log.")
            self.stopped.wait(0.3)
        raise RuntimeError("AI engine startup timed out. Restart TechAid IO and try again.")

    def ensure(self, model, report):
        with self.lock:
            self.start(report)
            with self.request("/api/tags") as response:
                models = json.load(response).get("models", [])
            normalized = model if ":" in model.rsplit("/", 1)[-1] else model + ":latest"
            if any(item.get("name") in (model, normalized) for item in models):
                return
            report("First setup: downloading " + model + " (several GB; internet required)…")
            success = False
            with self.request("/api/pull", {"model": model, "stream": True}, timeout=60) as response:
                for line in response:
                    if self.stopped.is_set():
                        raise RuntimeError("Setup stopped. Reopen the app to resume.")
                    if not line.strip():
                        continue
                    event = json.loads(line)
                    if event.get("error"):
                        raise RuntimeError(event["error"])
                    status = event.get("status", "Downloading model")
                    total, completed = event.get("total", 0), event.get("completed", 0)
                    if total:
                        status += f" — {completed / total:.0%} ({completed / 1e9:.2f}/{total / 1e9:.2f} GB)"
                    report(status)
                    if event.get("status") == "success":
                        success = True
            if not success:
                raise RuntimeError("Model download did not finish. Check internet and disk space, then retry.")

    def close(self):
        self.stopped.set()
        # Never terminate an Ollama server that this app did not start.
        if self.process and self.process.poll() is None:
            self.process.terminate()


# -------------------- OLLAMA CONNECTION --------------------

def stream_chat(model, messages):
    """Send a conversation to Ollama and receive streamed text."""

    data = json.dumps({
        "model": model,
        "messages": messages,
        "stream": True,
        "think": False,
        "options": {"num_ctx": 8192 if any("--- Attached file:" in m.get("content", "") for m in messages) else 2048, "num_predict": 2048},
        "keep_alive": 0
    }).encode("utf-8")

    request = urllib.request.Request(
        ENDPOINT,
        data=data,
        headers={"Content-Type": "application/json"}
    )

    # Bypass proxies because Ollama is running on this computer.
    opener = urllib.request.build_opener(
        urllib.request.ProxyHandler({})
    )

    received_answer = False
    received_thinking = False
    with opener.open(request, timeout=300) as response:
        for line in response:
            if not line.strip():
                continue

            event = json.loads(line)

            if event.get("error"):
                raise RuntimeError(event["error"])

            message = event.get("message") or {}
            text = message.get("content", "")
            received_thinking = received_thinking or bool(message.get("thinking"))
            if text:
                received_answer = received_answer or bool(text.strip())
                yield text

            if event.get("done"):
                if not received_answer:
                    detail = ('The model generated thinking without a final answer. '
                              if received_thinking else 'Ollama returned an empty answer. ')
                    raise RuntimeError(detail + 'Try a new conversation. If this repeats, test the model in Ollama or choose another installed model in Settings.')
                if event.get('done_reason') == 'length':
                    raise RuntimeError('The reply reached the output limit and is incomplete. Ask for a shorter answer or one section at a time.')
                return

    raise RuntimeError("Ollama disconnected before finishing.")


# -------------------- LOCAL CHAT STORAGE --------------------

class Store:
    """Save chats and settings locally using SQLite."""

    def __init__(self):
        folder = Path(
            os.environ.get(
                "LOCALAPPDATA",
                str(Path.home() / ".local" / "share")
            )
        ) / "TechAidIO"

        folder.mkdir(parents=True, exist_ok=True)

        self.db = sqlite3.connect(folder / "chats.sqlite3", check_same_thread=False)

        # These tables are compatible with the previous app version.
        self.db.executescript("""
            CREATE TABLE IF NOT EXISTS chats (
                id TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                updated REAL NOT NULL
            );

            CREATE TABLE IF NOT EXISTS messages (
                id INTEGER PRIMARY KEY,
                chat TEXT NOT NULL,
                role TEXT NOT NULL,
                content TEXT NOT NULL,
                status TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS settings (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );
        """)

        with self.db:
            # Keep an existing personality while updating the assistant's name.
            self.db.execute(
                "UPDATE settings SET value=replace(value, 'Jarvis', 'Mood') WHERE key='prompt'"
            )
            self.db.execute(
                "UPDATE messages SET status='interrupted' "
                "WHERE status='pending'"
            )

    def setting(self, key, default):
        row = self.db.execute(
            "SELECT value FROM settings WHERE key=?",
            (key,)
        ).fetchone()

        return row[0] if row else default

    def save_setting(self, key, value):
        with self.db:
            self.db.execute(
                "INSERT OR REPLACE INTO settings VALUES (?, ?)",
                (key, value)
            )

    def chats(self, search=""):
        rows = self.db.execute(
            "SELECT id, title FROM chats ORDER BY updated DESC"
        ).fetchall()

        return [
            (cid, title)
            for cid, title in rows
            if search.casefold() in title.casefold()
        ]

    def title(self, cid):
        row = self.db.execute(
            "SELECT title FROM chats WHERE id=?",
            (cid,)
        ).fetchone()

        return row[0] if row else "New chat"

    def new(self):
        cid = uuid.uuid4().hex

        with self.db:
            self.db.execute(
                "INSERT INTO chats VALUES (?, ?, ?)",
                (cid, "New chat", time.time())
            )

        return cid

    def messages(self, cid):
        return self.db.execute(
            "SELECT role, content, status FROM messages "
            "WHERE chat=? ORDER BY id",
            (cid,)
        ).fetchall()

    def begin(self, cid, text):
        first_message = not self.messages(cid)

        with self.db:
            if first_message:
                title = " ".join(text.split())[:48]

                self.db.execute(
                    "UPDATE chats SET title=? WHERE id=?",
                    (title, cid)
                )

            self.db.execute(
                "UPDATE chats SET updated=? WHERE id=?",
                (time.time(), cid)
            )

            user_id = self.db.execute(
                "INSERT INTO messages "
                "(chat, role, content, status) VALUES (?, ?, ?, ?)",
                (cid, "user", text, "pending")
            ).lastrowid

            assistant_id = self.db.execute(
                "INSERT INTO messages "
                "(chat, role, content, status) VALUES (?, ?, ?, ?)",
                (cid, "assistant", "", "pending")
            ).lastrowid

        return user_id, assistant_id

    def finish(self, ids, content, status):
        with self.db:
            self.db.execute(
                "UPDATE messages SET status=? WHERE id=?",
                (status, ids[0])
            )

            self.db.execute(
                "UPDATE messages SET content=?, status=? WHERE id=?",
                (content, status, ids[1])
            )

    def context(self, cid):
        return [{"role": role, "content": content[:16000 if "--- Attached file:" in content else 2500]}
                for role, content, state in self.messages(cid) if state == "complete"][-6:]

    def rename(self, cid, title):
        with self.db:
            self.db.execute(
                "UPDATE chats SET title=? WHERE id=?",
                (title, cid)
            )

    def delete(self, cid):
        with self.db:
            # Clean up optional data left by older versions only when deleting its chat.
            for table in ("market_snapshots", "picture_notes"):
                if self.db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,)).fetchone():
                    self.db.execute("DELETE FROM " + table + " WHERE message_id IN "
                                    "(SELECT id FROM messages WHERE chat=?)", (cid,))
            self.db.execute(
                "DELETE FROM messages WHERE chat=?",
                (cid,)
            )
            self.db.execute(
                "DELETE FROM chats WHERE id=?",
                (cid,)
            )


# -------------------- THREAD-SAFE DESKTOP BRIDGE --------------------

class DesktopAPI:
    """Only explicit UI actions are exposed to the embedded page.

    pywebview calls methods on separate threads. All database access and shared
    state use one re-entrant lock; network and speech run outside that lock.
    """
    def __init__(self):
        self._lock = threading.RLock()
        self._store = Store()
        # The requested Windows build always starts with the original Llama model.
        # Apply the same preset once when upgrading the Python source app.
        if getattr(sys, 'frozen', False) or self._store.setting('mood_llama_preset', '0') != '1':
            self._store.save_setting('model', DEFAULT_MODEL)
            self._store.save_setting('mood_llama_preset', '1')
        self._runtime = LocalRuntime()
        self._voice = KokoroVoice()
        self._window = None
        self._closed = False
        self._running = None
        self._ids = None
        self._partial = ''
        self._status = 'Ready when you are'
        self._error = ''
        self._token = 0
        self._revision = 0
        self._setup_running = False
        self._ai_ready = False

    def prepare_ai(self):
        """First-run setup happens off the UI thread and never changes chats."""
        with self._lock:
            if self._closed or self._setup_running or self._running:
                return False
            self._setup_running = True
            self._ai_ready = False
            self._error = ''
            self._status = 'Preparing Mood. First-time setup may download several GB…'
            model = self._store.setting('model', DEFAULT_MODEL)
            threading.Thread(target=self._prepare_ai_worker, args=(model,), daemon=True).start()
        return True

    def _prepare_ai_worker(self, model):
        failure = ''
        try:
            self._runtime.ensure(model, self._report)
        except Exception as exc:
            failure = str(exc)
        with self._lock:
            if self._closed:
                return
            self._setup_running = False
            self._ai_ready = not failure
            self._error = failure
            self._status = 'Setup needs attention. Check your connection and press Retry setup.' if failure else 'Mood is ready · ' + model

    def _valid(self, cid):
        if not cid or not self._store.db.execute('SELECT 1 FROM chats WHERE id=?', (cid,)).fetchone():
            raise ValueError('This conversation is no longer available.')

    def state(self, cid=None):
        with self._lock:
            if self._closed:
                return {'closed': True}
            rows = []
            if cid:
                self._valid(cid)
                rows = [{'role': role, 'content': self._partial if (
                    cid == self._running and role == 'assistant' and status == 'pending'
                ) else content, 'status': status}
                    for role, content, status in self._store.messages(cid)]
            return {
                'chats': [{'id': key, 'title': title} for key, title in self._store.chats()],
                'messages': rows, 'running': self._running,
                'setup_running': self._setup_running, 'ai_ready': self._ai_ready,
                'status': self._status, 'error': self._error,
                'revision': self._revision,
                'settings': {
                    'model': self._store.setting('model', DEFAULT_MODEL),
                    'prompt': self._store.setting('prompt', DEFAULT_PROMPT),
                    'theme': self._store.setting('theme', 'system'),
                    'read_aloud': self._store.setting('read_aloud', '1') == '1',
                    'motion': self._store.setting('motion', '1') == '1',
                },
                'voice_available': True,
            }

    def send(self, cid, text, attachments=None):
        attachments = attachments or []
        if not isinstance(attachments, list) or len(attachments) > 5:
            raise ValueError('Attach up to five text or code files.')
        parts = []
        total = 0
        for attachment in attachments:
            if not isinstance(attachment, dict):
                raise ValueError('Invalid attachment.')
            name, content = attachment.get('name'), attachment.get('content')
            if not isinstance(name, str) or not name or len(name) > 255:
                raise ValueError('Invalid filename.')
            if not isinstance(content, str) or '\x00' in content:
                raise ValueError('Only plain text and code files are supported.')
            total += len(content)
            if total > 12000:
                raise ValueError('Attached files must total 12,000 characters or fewer.')
            parts.append('--- Attached file: ' + name.replace('\n', ' ') + ' ---\n' + content)
        if not isinstance(text, str):
            raise ValueError('Invalid message.')
        if parts:
            text = (text.strip() or 'Please review the attached files.') + '\n\n' + '\n\n'.join(parts)

        if not isinstance(text, str) or not text.strip():
            raise ValueError('Write a message first.')
        if len(text) > 60000:
            raise ValueError('Please shorten your message to under 60,000 characters.')
        with self._lock:
            if self._closed or self._running or self._setup_running:
                raise ValueError('Mood is preparing or answering. Please wait.')
            if cid:
                self._valid(cid)
            else:
                cid = self._store.new()
            text = text.strip()
            messages = self._store.context(cid)
            prompt = self._store.setting('prompt', DEFAULT_PROMPT)
            if prompt:
                messages.insert(0, {'role': 'system', 'content': prompt})
            messages.append({'role': 'user', 'content': text})
            model = self._store.setting('model', DEFAULT_MODEL)
            self._ids = self._store.begin(cid, text)
            self._running, self._partial, self._error = cid, '', ''
            self._status = 'Preparing your local model…'
            self._revision += 1
            self._token = self._voice.stop()
            threading.Thread(target=self._generate, args=(model, messages), daemon=True).start()
            return {'id': cid}

    def _report(self, text):
        with self._lock:
            self._status = text

    def _generate(self, model, messages):
        failure = ''
        try:
            self._runtime.ensure(model, self._report)
            self._report('Mood is thinking…')
            for chunk in stream_chat(model, messages):
                with self._lock:
                    if self._closed:
                        return
                    self._partial += chunk
                    self._status = 'Mood is responding…'
        except urllib.error.HTTPError as exc:
            failure = f'Ollama HTTP {exc.code}: ' + exc.read().decode('utf-8', errors='replace')[:600]
        except urllib.error.URLError:
            failure = 'The local AI engine could not be reached. Check Ollama, then send again.'
        except Exception as exc:
            failure = str(exc)
        with self._lock:
            if self._closed:
                return
            if not failure and not self._partial.strip():
                failure = 'The model returned no answer. Try a new conversation or test this model in Ollama.'
            self._store.finish(self._ids, self._partial, 'failed' if failure else 'complete')
            spoken = self._partial
            self._error = failure
            self._status = 'Something needs attention' if failure else 'Saved on this device'
            self._running, self._ids, self._partial = None, None, ''
            self._revision += 1
            read = self._store.setting('read_aloud', '1') == '1'
            token = self._token
        if read and not failure and spoken:
            self._speak(spoken, token)

    def _speak(self, text, token):
        try:
            self._voice.run(text, token)
        except Exception as exc:
            with self._lock:
                if token == self._token and not self._closed:
                    self._error = 'Kokoro voice: ' + str(exc)

    def test_voice(self):
        with self._lock:
            if self._closed or self._running:
                raise ValueError('Wait until Mood finishes answering before testing the voice.')
            self._error = ''
            token = self._voice.stop()
            self._token = token
            threading.Thread(target=self._speak,
                args=("Hi, I'm Mood. What would you like to work on today?", token), daemon=True).start()
        return True

    def stop_voice(self):
        with self._lock:
            self._token = self._voice.stop()
        return True

    def rename(self, cid, title):
        with self._lock:
            self._valid(cid)
            if not isinstance(title, str) or not title.strip():
                raise ValueError('Enter a conversation name.')
            self._store.rename(cid, title.strip()[:100])
            self._revision += 1
        return True

    def delete(self, cid):
        with self._lock:
            self._valid(cid)
            if cid == self._running:
                raise ValueError('Wait for this response before deleting the conversation.')
            self._store.delete(cid)
            self._revision += 1
        return True

    def save_settings(self, values):
        with self._lock:
            model = str(values.get('model', '')).strip()
            if not model or len(model) > 200:
                raise ValueError('Enter a valid Ollama model name.')
            theme = values.get('theme', 'system')
            if theme not in ('light', 'dark', 'system'):
                raise ValueError('Choose light, dark, or system appearance.')
            self._store.save_setting('model', model)
            self._store.save_setting('prompt', str(values.get('prompt', ''))[:12000])
            self._store.save_setting('theme', theme)
            self._store.save_setting('read_aloud', '1' if values.get('read_aloud') else '0')
            self._store.save_setting('motion', '1' if values.get('motion', True) else '0')
            if not values.get('read_aloud'):
                self._token = self._voice.stop()
        return True

    def export_chat(self, cid):
        # Snapshot under the lock; release it before opening a native save dialog.
        with self._lock:
            self._valid(cid)
            content = 'TechAid IO / Mood\n' + self._store.title(cid) + '\n\n'
            for role, text, status in self._store.messages(cid):
                if role == 'assistant' and status == 'pending' and cid == self._running:
                    text = self._partial
                content += f'{role.upper()} [{status}]\n{text}\n\n'
        import webview
        result = self._window.create_file_dialog(
            webview.FileDialog.SAVE, save_filename='Mood-chat.txt',
            file_types=('Text files (*.txt)',))
        if result:
            destination = result if isinstance(result, str) else result[0]
            Path(destination).write_text(content, encoding='utf-8')
            return True
        return False

    def _close(self):
        with self._lock:
            if self._closed:
                return
            self._closed = True
            self._voice.stop()
            if self._running and self._ids:
                self._store.finish(self._ids, self._partial, 'interrupted')
            self._runtime.close()
            self._store.db.close()


# -------------------- EMBEDDED INTERFACE --------------------
# All assets are inline. Model messages are inserted using textContent, never
# executed as HTML. Glass blurs the ambient layers inside the app, not the OS.
