def _set_mood_window_icon(window, handles):
    """Apply embedded artwork to the Windows title bar without a new dependency."""
    if sys.platform != 'win32':
        return
    import ctypes
    from ctypes import wintypes
    try:
        folder = Path(os.environ.get('LOCALAPPDATA', str(Path.home()))) / 'TechAidIO'
        folder.mkdir(parents=True, exist_ok=True)
        icon_path = folder / 'Mood.ico'
        icon_path.write_bytes(base64.b64decode(MOOD_ICON_ICO))
        user32 = ctypes.WinDLL('user32', use_last_error=True)
        user32.LoadImageW.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR, wintypes.UINT,
                                     ctypes.c_int, ctypes.c_int, wintypes.UINT]
        user32.LoadImageW.restype = wintypes.HANDLE
        user32.SendMessageW.argtypes = [wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
        user32.SendMessageW.restype = ctypes.c_ssize_t
        hwnd = window.native.Handle.ToInt64()
        for kind, size in ((0, 16), (1, 32)):
            handle = user32.LoadImageW(None, str(icon_path), 1, size, size, 0x10)
            if handle:
                handles.append(handle)
                user32.SendMessageW(hwnd, 0x0080, kind, handle)
    except Exception as exc:
        print('Mood window icon could not be applied:', exc)


def _release_mood_icons(handles):
    if sys.platform == 'win32' and handles:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.WinDLL('user32', use_last_error=True)
        user32.DestroyIcon.argtypes = [wintypes.HANDLE]
        user32.DestroyIcon.restype = wintypes.BOOL
        for handle in handles:
            user32.DestroyIcon(handle)


def main():
    try:
        import webview
    except ImportError:
        print('Install the desktop dependency first:\n  py -3 -m pip install "pywebview>=6.0,<7"')
        raise SystemExit(1)
    api = DesktopAPI()
    icon_handles = []
    try:
        window = webview.create_window(
            'Mood — TechAid IO', html=HTML, js_api=api,
            width=1180, height=820, min_size=(820, 580),
            background_color='#f5f5f7', text_select=True)
        api._window = window
        window.events.shown += lambda: _set_mood_window_icon(window, icon_handles)
        window.events.closing += api._close
        # Modern Windows rendering supports backdrop-filter and native dialogs.
        webview.start(gui='edgechromium' if sys.platform == 'win32' else None)
    finally:
        api._close()
        _release_mood_icons(icon_handles)


if __name__ == '__main__':
    main()
